// PeerChat discovery service, Milestones 1-2.
// Purpose: authenticate accounts, publish public device identities/presence, and own friendship metadata.
// Inputs: a TLS-protected, length-limited JSON request per connection. Outputs: JSON responses.
// Security: passwords are PBKDF2-SHA256 hashes; session tokens are random and stored only hashed.
// The service never accepts private device keys or message contents. Ordinary sockets are owned by
// short-lived workers; authenticated event subscriptions remain owned until the client disconnects.
using System;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.Linq;
using System.IO;
using System.Net;
using System.Net.NetworkInformation;
using System.Net.Security;
using System.Net.Sockets;
using System.IO.Pipes;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using System.Runtime.InteropServices;
using PeerChat.ServerShared;
using PeerChat;

namespace PeerChat.Server {
    static class Sqlite {
        [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl,CharSet=CharSet.Unicode)] internal static extern int sqlite3_open16(string filename, out IntPtr database);
        [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_close(IntPtr database);
        [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_exec(IntPtr database, string sql, IntPtr callback, IntPtr argument, out IntPtr error);
        [DllImport("winsqlite3.dll", CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_free(IntPtr value);
    }

    // SQLite owns durable account state. All writes use a process-wide lock because this starter
    // service deliberately uses one embedded database rather than introducing another service.
    sealed class AccountDatabase : IDisposable {
        readonly object gate = new object(); readonly IntPtr database;
        public AccountDatabase(string path) {
            string fullPath=Path.GetFullPath(path);Console.WriteLine("Discovery account database: "+fullPath);
            if (Sqlite.sqlite3_open16(fullPath, out database) != 0) throw new InvalidOperationException("Cannot open server database.");
            Execute("PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;" +
                "CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, password_salt BLOB NOT NULL, password_hash BLOB NOT NULL, discoverability TEXT NOT NULL DEFAULT 'public', created_utc INTEGER NOT NULL);" +
                "CREATE TABLE IF NOT EXISTS devices(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), public_identity TEXT NOT NULL UNIQUE, created_utc INTEGER NOT NULL);" +
                "CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), expires_utc INTEGER NOT NULL);" +
                "CREATE TABLE IF NOT EXISTS presence(device_id INTEGER PRIMARY KEY REFERENCES devices(id), seen_utc INTEGER NOT NULL, endpoint_host TEXT, endpoint_port INTEGER, public_endpoint_host TEXT, public_endpoint_port INTEGER, public_candidate_source TEXT, observed_classification TEXT);" +
                "CREATE TABLE IF NOT EXISTS friend_requests(sender_id INTEGER NOT NULL REFERENCES accounts(id), recipient_id INTEGER NOT NULL REFERENCES accounts(id), state TEXT NOT NULL, created_utc INTEGER NOT NULL, updated_utc INTEGER NOT NULL, PRIMARY KEY(sender_id,recipient_id));" +
                "CREATE INDEX IF NOT EXISTS friend_requests_recipient_state ON friend_requests(recipient_id,state,updated_utc);" +
                "CREATE TABLE IF NOT EXISTS friendships(account_low INTEGER NOT NULL REFERENCES accounts(id), account_high INTEGER NOT NULL REFERENCES accounts(id), created_utc INTEGER NOT NULL, PRIMARY KEY(account_low,account_high));" +
                "CREATE TABLE IF NOT EXISTS account_blocks(blocker_id INTEGER NOT NULL REFERENCES accounts(id), blocked_id INTEGER NOT NULL REFERENCES accounts(id), created_utc INTEGER NOT NULL, PRIMARY KEY(blocker_id,blocked_id));");
            // Existing Milestone 1 databases predate privacy controls. Add the non-sensitive
            // default once; future Friends Only/Hidden settings use this same column.
            try { Execute("ALTER TABLE accounts ADD COLUMN discoverability TEXT NOT NULL DEFAULT 'public';"); } catch { }
            // Endpoint candidates are deliberately optional. Older Milestone 1 databases receive
            // these nullable columns without changing their account/device identities.
            try { Execute("ALTER TABLE presence ADD COLUMN endpoint_host TEXT;"); } catch { }
            try { Execute("ALTER TABLE presence ADD COLUMN endpoint_port INTEGER;"); } catch { }
            try { Execute("ALTER TABLE presence ADD COLUMN public_endpoint_host TEXT;"); } catch { }
            try { Execute("ALTER TABLE presence ADD COLUMN public_endpoint_port INTEGER;"); } catch { }
            try { Execute("ALTER TABLE presence ADD COLUMN public_candidate_source TEXT;"); } catch { }
            try { Execute("ALTER TABLE presence ADD COLUMN observed_classification TEXT;"); } catch { }
        }
        public void Execute(string sql) { lock (gate) { IntPtr error; if (Sqlite.sqlite3_exec(database, sql, IntPtr.Zero, IntPtr.Zero, out error) != 0) { string message=error==IntPtr.Zero?"SQLite error":Marshal.PtrToStringAnsi(error); if(error!=IntPtr.Zero)Sqlite.sqlite3_free(error); throw new InvalidOperationException(message); } } }
        // Parameter values are hex/base64url or validated identifiers, never interpolated raw user input.
        static string Quote(string value) { return "'" + value.Replace("'", "''") + "'"; }
        static string Hex(byte[] value) { var b=new StringBuilder(value.Length*2); foreach(byte x in value)b.Append(x.ToString("x2")); return b.ToString(); }
        static string ScalarText(IntPtr database, string sql) { IntPtr statement=IntPtr.Zero; try { if(SqliteNative.prepare(database,sql,out statement)!=0)return null; return SqliteNative.step(statement)==100?SqliteNative.columnText(statement,0):null; } finally { if(statement!=IntPtr.Zero)SqliteNative.finalize(statement); } }
        static long ScalarLong(IntPtr database, string sql) { var value=ScalarText(database,sql); long parsed; return Int64.TryParse(value,out parsed)?parsed:0; }
        public bool UsernameExists(string username) { lock(gate)return ScalarLong(database,"SELECT count(*) FROM accounts WHERE username="+Quote(username))>0; }
        // An account is only useful for discovery if it owns a public device identity.  Keep both
        // inserts in one transaction so a reused device key cannot leave behind an account that
        // cannot be found (or a partial account after a database error).
        public long CreateAccountWithDevice(string username, byte[] salt, byte[] hash, string publicIdentity) { lock(gate) { Execute("BEGIN IMMEDIATE;"); try { Execute("INSERT INTO accounts(username,password_salt,password_hash,created_utc) VALUES("+Quote(username)+",X'"+Hex(salt)+"',X'"+Hex(hash)+"',"+UnixNow()+");"); long id=ScalarLong(database,"SELECT last_insert_rowid();"); Execute("INSERT INTO devices(account_id,public_identity,created_utc) VALUES("+id+","+Quote(publicIdentity)+","+UnixNow()+");"); Execute("COMMIT;"); return id; } catch { try { Execute("ROLLBACK;"); } catch {} throw; } } }
        public bool DeviceIdentityExists(string publicIdentity) { lock(gate) return ScalarLong(database,"SELECT count(*) FROM devices WHERE public_identity="+Quote(publicIdentity))>0; }
        public bool PasswordMatches(string username, Func<byte[], byte[], bool> verifier, out long accountId) { lock(gate) { IntPtr s=IntPtr.Zero; accountId=0; try { if(SqliteNative.prepare(database,"SELECT id,password_salt,password_hash FROM accounts WHERE username="+Quote(username),out s)!=0||SqliteNative.step(s)!=100)return false; accountId=SqliteNative.columnLong(s,0); return verifier(SqliteNative.columnBlob(s,1),SqliteNative.columnBlob(s,2)); } finally { if(s!=IntPtr.Zero)SqliteNative.finalize(s); } } }
        public bool AddDevice(long accountId,string publicIdentity) { lock(gate){long owner=ScalarLong(database,"SELECT account_id FROM devices WHERE public_identity="+Quote(publicIdentity));if(owner!=0)return owner==accountId;Execute("INSERT INTO devices(account_id,public_identity,created_utc) VALUES("+accountId+","+Quote(publicIdentity)+","+UnixNow()+");");return true;} }
        public bool OwnsDevice(long accountId,string publicIdentity){lock(gate)return ScalarLong(database,"SELECT count(*) FROM devices WHERE account_id="+accountId+" AND public_identity="+Quote(publicIdentity))>0;}
        public void CreateSession(string tokenHash,long accountId,long expires) { lock(gate) Execute("DELETE FROM sessions WHERE expires_utc<"+UnixNow()+"; INSERT INTO sessions(token_hash,account_id,expires_utc) VALUES("+Quote(tokenHash)+","+accountId+","+expires+");"); }
        public long Authenticate(string tokenHash) { lock(gate)return ScalarLong(database,"SELECT account_id FROM sessions WHERE token_hash="+Quote(tokenHash)+" AND expires_utc>="+UnixNow()); }
        public void RevokeSession(string tokenHash) { lock(gate) Execute("DELETE FROM sessions WHERE token_hash="+Quote(tokenHash)+";"); }
        public void TouchPresence(long accountId,string publicIdentity,string endpointHost,int endpointPort,string publicHost,int publicPort,string publicSource,string observedClassification) { lock(gate) Execute("INSERT INTO presence(device_id,seen_utc,endpoint_host,endpoint_port,public_endpoint_host,public_endpoint_port,public_candidate_source,observed_classification) SELECT id,"+UnixNow()+","+Quote(endpointHost??"")+","+endpointPort+","+Quote(publicHost??"")+","+publicPort+","+Quote(publicSource??"")+","+Quote(observedClassification??"")+" FROM devices WHERE account_id="+accountId+" AND public_identity="+Quote(publicIdentity)+" ON CONFLICT(device_id) DO UPDATE SET seen_utc=excluded.seen_utc,endpoint_host=excluded.endpoint_host,endpoint_port=excluded.endpoint_port,public_endpoint_host=excluded.public_endpoint_host,public_endpoint_port=excluded.public_endpoint_port,public_candidate_source=excluded.public_candidate_source,observed_classification=excluded.observed_classification;"); }
        public Dictionary<string,object> Search(string username,long viewerAccount) { lock(gate) { IntPtr s=IntPtr.Zero; try { string sql="SELECT a.id,a.username,COALESCE((SELECT d2.public_identity FROM presence p2 JOIN devices d2 ON d2.id=p2.device_id WHERE d2.account_id=a.id ORDER BY p2.seen_utc DESC LIMIT 1),(SELECT d3.public_identity FROM devices d3 WHERE d3.account_id=a.id ORDER BY d3.id LIMIT 1)),COALESCE((SELECT max(p3.seen_utc) FROM presence p3 JOIN devices d3 ON d3.id=p3.device_id WHERE d3.account_id=a.id),0) FROM accounts a WHERE a.id<>"+viewerAccount+" AND a.discoverability='public' AND a.username="+Quote(username)+" AND NOT EXISTS (SELECT 1 FROM account_blocks b WHERE (b.blocker_id="+viewerAccount+" AND b.blocked_id=a.id) OR (b.blocker_id=a.id AND b.blocked_id="+viewerAccount+")) ORDER BY a.id LIMIT 1"; if(SqliteNative.prepare(database,sql,out s)!=0||SqliteNative.step(s)!=100)return null; long seen=SqliteNative.columnLong(s,3); return new Dictionary<string,object>{{"accountId",SqliteNative.columnLong(s,0)},{"username",SqliteNative.columnText(s,1)},{"publicIdentity",SqliteNative.columnText(s,2)},{"online",seen>=UnixNow()-90}}; } finally { if(s!=IntPtr.Zero)SqliteNative.finalize(s); } } }
        // accounts.username is UNIQUE COLLATE NOCASE, so this prefix query uses the account index.
        // Discovery returns only the public identity reference required for later friend actions.
        public List<Dictionary<string,object>> Suggestions(string prefix,long excludeAccount,int limit){lock(gate){var list=new List<Dictionary<string,object>>();IntPtr s=IntPtr.Zero;try{string sql="SELECT a.id,a.username,COALESCE((SELECT d2.public_identity FROM presence p2 JOIN devices d2 ON d2.id=p2.device_id WHERE d2.account_id=a.id ORDER BY p2.seen_utc DESC LIMIT 1),(SELECT d3.public_identity FROM devices d3 WHERE d3.account_id=a.id ORDER BY d3.id LIMIT 1)),COALESCE((SELECT max(p3.seen_utc) FROM presence p3 JOIN devices d3 ON d3.id=p3.device_id WHERE d3.account_id=a.id),0) FROM accounts a WHERE a.id<>"+excludeAccount+" AND a.discoverability='public' AND a.username LIKE "+Quote(prefix+"%")+" ESCAPE '\\' AND NOT EXISTS (SELECT 1 FROM account_blocks b WHERE (b.blocker_id="+excludeAccount+" AND b.blocked_id=a.id) OR (b.blocker_id=a.id AND b.blocked_id="+excludeAccount+")) ORDER BY a.username,a.id LIMIT "+limit;if(SqliteNative.prepare(database,sql,out s)!=0)return list;while(SqliteNative.step(s)==100){long seen=SqliteNative.columnLong(s,3);list.Add(new Dictionary<string,object>{{"accountId",SqliteNative.columnLong(s,0)},{"username",SqliteNative.columnText(s,1)},{"publicIdentity",SqliteNative.columnText(s,2)},{"online",seen>=UnixNow()-90}});}return list;}finally{if(s!=IntPtr.Zero)SqliteNative.finalize(s);}}}
        static long Low(long a,long b){return Math.Min(a,b);} static long High(long a,long b){return Math.Max(a,b);}
        bool Exists(long accountId){return ScalarLong(database,"SELECT count(*) FROM accounts WHERE id="+accountId)>0;}
        bool Blocked(long a,long b){return ScalarLong(database,"SELECT count(*) FROM account_blocks WHERE (blocker_id="+a+" AND blocked_id="+b+") OR (blocker_id="+b+" AND blocked_id="+a+")")>0;}
        // Used by the notification layer only to decide whether a presence update is
        // appropriate for a subscriber. It never exposes friendship data to the client.
        public bool Friends(long a,long b){return ScalarLong(database,"SELECT count(*) FROM friendships WHERE account_low="+Low(a,b)+" AND account_high="+High(a,b))>0;}
        public bool RelayAuthorized(long a,long b){lock(gate)return Friends(a,b)||ScalarLong(database,"SELECT count(*) FROM friend_requests WHERE state='pending' AND ((sender_id="+a+" AND recipient_id="+b+") OR (sender_id="+b+" AND recipient_id="+a+"))")>0;}
        void MakeFriends(long a,long b){Execute("INSERT OR IGNORE INTO friendships(account_low,account_high,created_utc) VALUES("+Low(a,b)+","+High(a,b)+","+UnixNow()+");");}
        // Every state transition is serialized and transactional. The authenticated account ID is
        // supplied by the server session lookup, never by a client-provided sender field.
        public string SendFriendRequest(long sender,long recipient){lock(gate){if(sender==recipient)return "self_request";if(!Exists(recipient))return "not_found";Execute("BEGIN IMMEDIATE;");try{if(Blocked(sender,recipient)){Execute("ROLLBACK;");return "blocked";}if(Friends(sender,recipient)){Execute("ROLLBACK;");return "already_friends";}if(ScalarLong(database,"SELECT count(*) FROM friend_requests WHERE sender_id="+sender+" AND recipient_id="+recipient+" AND state='pending'")>0){Execute("ROLLBACK;");return "already_pending";}if(ScalarLong(database,"SELECT count(*) FROM friend_requests WHERE sender_id="+recipient+" AND recipient_id="+sender+" AND state='pending'")>0){MakeFriends(sender,recipient);Execute("DELETE FROM friend_requests WHERE (sender_id="+sender+" AND recipient_id="+recipient+") OR (sender_id="+recipient+" AND recipient_id="+sender+");");Execute("COMMIT;");return "accepted_crossed";}long now=UnixNow();Execute("INSERT INTO friend_requests(sender_id,recipient_id,state,created_utc,updated_utc) VALUES("+sender+","+recipient+",'pending',"+now+","+now+") ON CONFLICT(sender_id,recipient_id) DO UPDATE SET state='pending',updated_utc=excluded.updated_utc;");Execute("COMMIT;");return "pending";}catch{try{Execute("ROLLBACK;");}catch{}throw;}}}
        public string RespondToRequest(long recipient,long sender,bool accept){lock(gate){Execute("BEGIN IMMEDIATE;");try{if(ScalarLong(database,"SELECT count(*) FROM friend_requests WHERE sender_id="+sender+" AND recipient_id="+recipient+" AND state='pending'")==0){Execute("ROLLBACK;");return "not_found";}if(accept){if(Blocked(sender,recipient)){Execute("ROLLBACK;");return "blocked";}MakeFriends(sender,recipient);Execute("DELETE FROM friend_requests WHERE sender_id="+sender+" AND recipient_id="+recipient+";");Execute("COMMIT;");return "friends";}Execute("UPDATE friend_requests SET state='rejected',updated_utc="+UnixNow()+" WHERE sender_id="+sender+" AND recipient_id="+recipient+";");Execute("COMMIT;");return "rejected";}catch{try{Execute("ROLLBACK;");}catch{}throw;}}}
        public string CancelRequest(long sender,long recipient){lock(gate){int before=(int)ScalarLong(database,"SELECT count(*) FROM friend_requests WHERE sender_id="+sender+" AND recipient_id="+recipient+" AND state='pending'");if(before==0)return "not_found";Execute("DELETE FROM friend_requests WHERE sender_id="+sender+" AND recipient_id="+recipient+" AND state='pending';");return "cancelled";}}
        public string RemoveFriend(long account,long other){lock(gate){int before=(int)ScalarLong(database,"SELECT count(*) FROM friendships WHERE account_low="+Low(account,other)+" AND account_high="+High(account,other));if(before==0)return "not_found";Execute("DELETE FROM friendships WHERE account_low="+Low(account,other)+" AND account_high="+High(account,other)+";");return "removed";}}
        public string SetBlocked(long account,long other,bool blocked){lock(gate){if(account==other)return "self_block";if(!Exists(other))return "not_found";if(blocked){Execute("BEGIN IMMEDIATE;");try{Execute("INSERT OR IGNORE INTO account_blocks(blocker_id,blocked_id,created_utc) VALUES("+account+","+other+","+UnixNow()+");");Execute("DELETE FROM friendships WHERE account_low="+Low(account,other)+" AND account_high="+High(account,other)+"; DELETE FROM friend_requests WHERE (sender_id="+account+" AND recipient_id="+other+") OR (sender_id="+other+" AND recipient_id="+account+");");Execute("COMMIT;");return "blocked";}catch{try{Execute("ROLLBACK;");}catch{}throw;}}Execute("DELETE FROM account_blocks WHERE blocker_id="+account+" AND blocked_id="+other+";");return "unblocked";}}
        List<Dictionary<string,object>> Profiles(string predicate,bool includeEndpoint){var list=new List<Dictionary<string,object>>();IntPtr s=IntPtr.Zero;try{string sql="SELECT a.id,a.username,COALESCE((SELECT d2.public_identity FROM presence p2 JOIN devices d2 ON d2.id=p2.device_id WHERE d2.account_id=a.id ORDER BY p2.seen_utc DESC LIMIT 1),(SELECT d3.public_identity FROM devices d3 WHERE d3.account_id=a.id ORDER BY d3.id LIMIT 1)),COALESCE((SELECT max(seen_utc) FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id),0),COALESCE((SELECT p.endpoint_host FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),''),COALESCE((SELECT p.endpoint_port FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),0),COALESCE((SELECT p.public_endpoint_host FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),''),COALESCE((SELECT p.public_endpoint_port FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),0),COALESCE((SELECT p.public_candidate_source FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),''),COALESCE((SELECT p.observed_classification FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id=a.id ORDER BY p.seen_utc DESC LIMIT 1),'') FROM accounts a WHERE "+predicate+" ORDER BY a.username";if(SqliteNative.prepare(database,sql,out s)!=0)return list;while(SqliteNative.step(s)==100){long seen=SqliteNative.columnLong(s,3);var profile=new Dictionary<string,object>{{"accountId",SqliteNative.columnLong(s,0)},{"username",SqliteNative.columnText(s,1)},{"publicIdentity",SqliteNative.columnText(s,2)},{"online",seen>=UnixNow()-90}};if(includeEndpoint){profile["endpointHost"]=SqliteNative.columnText(s,4)??"";profile["endpointPort"]=SqliteNative.columnLong(s,5);profile["publicEndpointHost"]=SqliteNative.columnText(s,6)??"";profile["publicEndpointPort"]=SqliteNative.columnLong(s,7);profile["candidateSeenUtc"]=seen;profile["publicCandidateSource"]=SqliteNative.columnText(s,8)??"";profile["observedAddressClassification"]=SqliteNative.columnText(s,9)??"";}list.Add(profile);}return list;}finally{if(s!=IntPtr.Zero)SqliteNative.finalize(s);}}
        public Dictionary<string,object> FriendState(long account){lock(gate){return new Dictionary<string,object>{{"incoming",Profiles("a.id IN (SELECT sender_id FROM friend_requests WHERE recipient_id="+account+" AND state='pending')",false)},{"outgoing",Profiles("a.id IN (SELECT recipient_id FROM friend_requests WHERE sender_id="+account+" AND state='pending')",false)},{"friends",Profiles("a.id IN (SELECT CASE WHEN account_low="+account+" THEN account_high ELSE account_low END FROM friendships WHERE account_low="+account+" OR account_high="+account+")",true)},{"blocked",Profiles("a.id IN (SELECT blocked_id FROM account_blocks WHERE blocker_id="+account+")",false)}};}}
        public Dictionary<string,object> Statistics(){lock(gate)return new Dictionary<string,object>{{"accounts",ScalarLong(database,"SELECT count(*) FROM accounts")},{"sessions",ScalarLong(database,"SELECT count(*) FROM sessions WHERE expires_utc>="+UnixNow())},{"present",ScalarLong(database,"SELECT count(*) FROM presence WHERE seen_utc>="+(UnixNow()-90))}};}
        public Dictionary<string,object> AdminLookup(string username){lock(gate){if(String.IsNullOrWhiteSpace(username))return null;IntPtr statement=IntPtr.Zero;try{if(SqliteNative.prepare(database,"SELECT id,username FROM accounts WHERE username="+Quote(username)+" COLLATE NOCASE LIMIT 1",out statement)!=0||SqliteNative.step(statement)!=100)return null;return new Dictionary<string,object>{{"accountId",SqliteNative.columnLong(statement,0)},{"username",SqliteNative.columnText(statement,1)}};}finally{if(statement!=IntPtr.Zero)SqliteNative.finalize(statement);}}}
        List<long> RelatedAccounts(long accountId){var result=new List<long>();IntPtr statement=IntPtr.Zero;try{string sql="SELECT DISTINCT related FROM (SELECT CASE WHEN account_low="+accountId+" THEN account_high ELSE account_low END AS related FROM friendships WHERE account_low="+accountId+" OR account_high="+accountId+" UNION SELECT CASE WHEN sender_id="+accountId+" THEN recipient_id ELSE sender_id END AS related FROM friend_requests WHERE sender_id="+accountId+" OR recipient_id="+accountId+" UNION SELECT CASE WHEN blocker_id="+accountId+" THEN blocked_id ELSE blocker_id END AS related FROM account_blocks WHERE blocker_id="+accountId+" OR blocked_id="+accountId+")";if(SqliteNative.prepare(database,sql,out statement)!=0)return result;while(SqliteNative.step(statement)==100)result.Add(SqliteNative.columnLong(statement,0));return result;}finally{if(statement!=IntPtr.Zero)SqliteNative.finalize(statement);}}
        public Dictionary<string,object> AdminDeleteAccount(long accountId){lock(gate){string username=Username(accountId);if(String.IsNullOrEmpty(username))return null;var related=RelatedAccounts(accountId);Execute("BEGIN IMMEDIATE;");try{Execute("DELETE FROM sessions WHERE account_id="+accountId+"; DELETE FROM presence WHERE device_id IN (SELECT id FROM devices WHERE account_id="+accountId+"); DELETE FROM friend_requests WHERE sender_id="+accountId+" OR recipient_id="+accountId+"; DELETE FROM friendships WHERE account_low="+accountId+" OR account_high="+accountId+"; DELETE FROM account_blocks WHERE blocker_id="+accountId+" OR blocked_id="+accountId+"; DELETE FROM devices WHERE account_id="+accountId+"; DELETE FROM accounts WHERE id="+accountId+";");Execute("COMMIT;");return new Dictionary<string,object>{{"accountId",accountId},{"username",username},{"relatedAccounts",related}};}catch{try{Execute("ROLLBACK;");}catch{}throw;}}}
        public bool IsPresent(long accountId){lock(gate)return ScalarLong(database,"SELECT count(*) FROM presence p JOIN devices d ON d.id=p.device_id WHERE d.account_id="+accountId+" AND p.seen_utc>="+(UnixNow()-90))>0;}
        public string Username(long accountId){lock(gate)return ScalarText(database,"SELECT username FROM accounts WHERE id="+accountId);}
        static long UnixNow(){return DateTimeOffset.UtcNow.ToUnixTimeSeconds();}
        public void Dispose(){Sqlite.sqlite3_close(database);}
    }
    static class SqliteNative {
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_prepare_v2(IntPtr d,string q,int n,out IntPtr s,IntPtr tail);
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_step(IntPtr s);
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_finalize(IntPtr s);
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern long sqlite3_column_int64(IntPtr s,int c);
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern IntPtr sqlite3_column_text(IntPtr s,int c);
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern IntPtr sqlite3_column_blob(IntPtr s,int c);
        [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)] internal static extern int sqlite3_column_bytes(IntPtr s,int c);
        internal static int prepare(IntPtr d,string q,out IntPtr s){return sqlite3_prepare_v2(d,q,-1,out s,IntPtr.Zero);} internal static int step(IntPtr s){return sqlite3_step(s);} internal static void finalize(IntPtr s){sqlite3_finalize(s);} internal static long columnLong(IntPtr s,int c){return sqlite3_column_int64(s,c);} internal static string columnText(IntPtr s,int c){var p=sqlite3_column_text(s,c);return p==IntPtr.Zero?null:Marshal.PtrToStringAnsi(p);} internal static byte[] columnBlob(IntPtr s,int c){int n=sqlite3_column_bytes(s,c);var p=sqlite3_column_blob(s,c);var b=new byte[n];if(n>0)Marshal.Copy(p,b,0,n);return b;}
    }
        sealed class DiscoveryServer {
        const int ProtocolVersion=1, MaxRequestBytes=4096, MaxRelayPayloadBytes=64*1024; readonly ServerConfiguration config; readonly AccountDatabase accounts; readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=MaxRequestBytes}; readonly X509Certificate2 certificate; TcpListener listener; volatile bool stopping; int connectedClients; DateTime startedUtc; string managementPipe; readonly object eventGate=new object(); readonly List<EventClient> eventClients=new List<EventClient>(); readonly HashSet<long> onlineAccounts=new HashSet<long>(); readonly Dictionary<long,string> onlineCandidateSignatures=new Dictionary<long,string>();
        sealed class EventClient : IDisposable { public readonly TcpClient Client; public readonly SslStream Tls; public readonly long AccountId; public readonly object Gate=new object(); public EventClient(TcpClient client,SslStream tls,long accountId){Client=client;Tls=tls;AccountId=accountId;} public void Dispose(){try{Tls.Dispose();}catch{}try{Client.Close();}catch{}} }
        sealed class RelayEndpoint {
            public readonly TcpClient Client;public readonly SslStream Tls;public readonly long AccountId,TargetAccountId;public readonly string DeviceId,TargetDeviceId,Binding;public readonly object WriteGate=new object();public readonly ManualResetEvent Ready=new ManualResetEvent(false);
            public RelayEndpoint Peer;public string SessionId;public bool Incoming;
            public RelayEndpoint(TcpClient client,SslStream tls,long account,string device,long target,string targetDevice){Client=client;Tls=tls;AccountId=account;DeviceId=device;TargetAccountId=target;TargetDeviceId=targetDevice;Binding=account+":"+device+">"+target+":"+targetDevice;}
        }
        readonly object relayGate=new object();readonly List<RelayEndpoint> waitingRelays=new List<RelayEndpoint>();readonly List<RelayEndpoint> relayEndpoints=new List<RelayEndpoint>();readonly HashSet<string> activeRelayBindings=new HashSet<string>(StringComparer.Ordinal);
        // A certificate can be loaded from a PFX for ordinary deployment or from CurrentUser\My
        // during local development. Neither path ever exposes its private key to clients.
        public DiscoveryServer(ServerConfiguration c){config=c;managementPipe=c.ManagementPipe;accounts=new AccountDatabase(c.DatabasePath);certificate=LoadCertificate(c);}
        static X509Certificate2 LoadCertificate(ServerConfiguration config){if(!String.IsNullOrWhiteSpace(config.CertificateThumbprint)){var store=new X509Store(StoreName.My,StoreLocation.CurrentUser);store.Open(OpenFlags.ReadOnly);try{var found=store.Certificates.Find(X509FindType.FindByThumbprint,config.CertificateThumbprint.Replace(" ",""),false);if(found.Count==0||!found[0].HasPrivateKey)throw new InvalidOperationException("Configured certificate thumbprint was not found with a private key in CurrentUser\\My.");return found[0];}finally{store.Close();}}return new X509Certificate2(config.CertificatePath,config.CertificatePassword,X509KeyStorageFlags.UserKeySet|X509KeyStorageFlags.PersistKeySet);}
        static bool ValidUsername(string value){if(String.IsNullOrEmpty(value)||value.Length<3||value.Length>32)return false;foreach(char c in value)if(!(Char.IsLetterOrDigit(c)||c=='-'||c=='_'))return false;return true;}
        static bool ValidIdentity(string value){return !String.IsNullOrEmpty(value)&&value.Length>=32&&value.Length<=2048;}
        static bool ValidEndpoint(string host,int port){if(String.IsNullOrEmpty(host))return port==0;if(host.Length>253||port<1||port>65535)return false;return !host.Any(c=>Char.IsWhiteSpace(c)||Char.IsControl(c));}
        static bool IsLocalInterfaceAddress(string host){IPAddress address;if(!IPAddress.TryParse(host,out address))return false;try{return NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up).SelectMany(n=>n.GetIPProperties().UnicastAddresses).Any(u=>u.Address.Equals(address));}catch{return false;}}
        static bool IsUsablePublicIpv4(string host,out string classification){classification="Server-observed Internet address";IPAddress address;if(!IPAddress.TryParse(host,out address)||address.AddressFamily!=AddressFamily.InterNetwork){classification=String.IsNullOrEmpty(host)?"Missing": "Not an IPv4 address";return false;}byte[] b=address.GetAddressBytes();if(address.Equals(IPAddress.Loopback)||b[0]==127){classification="Loopback — rejected as public candidate";return false;}if(address.Equals(IPAddress.Any)||b[0]==0){classification="Unspecified — rejected as public candidate";return false;}if(b[0]==10||(b[0]==172&&b[1]>=16&&b[1]<=31)||(b[0]==192&&b[1]==168)){classification="Private RFC1918 — rejected as public candidate";return false;}if(b[0]==169&&b[1]==254){classification="Link-local — rejected as public candidate";return false;}if(b[0]==100&&b[1]>=64&&b[1]<=127){classification="Shared address space — rejected as public candidate";return false;}if(b[0]>=224){classification="Multicast/reserved — rejected as public candidate";return false;}return true;}
        static string RandomToken(){var b=new byte[32];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
        static string TokenHash(string token){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(token))).Replace("-","").ToLowerInvariant();}
        static byte[] PasswordHash(string password,byte[] salt){using(var kdf=new Rfc2898DeriveBytes(password,salt,310000,HashAlgorithmName.SHA256))return kdf.GetBytes(32);}
        // Do not use ordinary equality here: its early exit can leak how much of a stored password
        // verifier matched. .NET Framework lacks the public FixedTimeEquals API available on newer runtimes.
        static bool ConstantTimeEquals(byte[] a,byte[] b){if(a==null||b==null||a.Length!=b.Length)return false;int difference=0;for(int i=0;i<a.Length;i++)difference|=a[i]^b[i];return difference==0;}
        void Broadcast(long accountId,long other,string eventName,bool includeOther=true){var payload=Encoding.UTF8.GetBytes(json.Serialize(new Dictionary<string,object>{{"ok",true},{"version",ProtocolVersion},{"type","friend_event"},{"event",eventName},{"accountId",other}}));List<EventClient> dead=new List<EventClient>();lock(eventGate){foreach(var subscriber in eventClients){if(subscriber.AccountId!=accountId&&(!includeOther||subscriber.AccountId!=other))continue;try{lock(subscriber.Gate)WriteFrame(subscriber.Tls,payload);}catch{dead.Add(subscriber);}}foreach(var client in dead)eventClients.Remove(client);}foreach(var client in dead)client.Dispose();}
        void BroadcastPresence(long accountId,string publicIdentity,string endpointHost,int endpointPort,string publicHost="",int publicPort=0,bool online=true){List<EventClient> dead=new List<EventClient>();string signature=(publicIdentity??"")+"|"+(endpointHost??"")+"|"+endpointPort+"|"+(publicHost??"")+"|"+publicPort;lock(eventGate){string previous;bool wasOnline=onlineAccounts.Contains(accountId);if(online&&wasOnline&&onlineCandidateSignatures.TryGetValue(accountId,out previous)&&previous==signature)return;if(online){onlineAccounts.Add(accountId);onlineCandidateSignatures[accountId]=signature;}else{onlineAccounts.Remove(accountId);onlineCandidateSignatures.Remove(accountId);}}var payload=Encoding.UTF8.GetBytes(json.Serialize(new Dictionary<string,object>{{"ok",true},{"version",ProtocolVersion},{"type","friend_event"},{"event","presence_changed"},{"accountId",accountId},{"publicIdentity",publicIdentity??""},{"endpointHost",endpointHost??""},{"endpointPort",endpointPort},{"publicEndpointHost",publicHost??""},{"publicEndpointPort",publicPort},{"online",online}}));lock(eventGate){foreach(var subscriber in eventClients){if(subscriber.AccountId==accountId||!accounts.Friends(accountId,subscriber.AccountId))continue;try{lock(subscriber.Gate)WriteFrame(subscriber.Tls,payload);}catch{dead.Add(subscriber);}}foreach(var client in dead)eventClients.Remove(client);}foreach(var client in dead)client.Dispose();}
        void PresenceMonitor(){while(!stopping){Thread.Sleep(10000);if(stopping)break;List<long> stale=new List<long>();lock(eventGate){foreach(var accountId in onlineAccounts)if(!accounts.IsPresent(accountId))stale.Add(accountId);foreach(var accountId in stale)onlineAccounts.Remove(accountId);}foreach(var accountId in stale)BroadcastPresence(accountId,"","",0,"",0,false);}}
        Dictionary<string,object> Handle(Dictionary<string,object> request,string observedHost="",int observedPort=0) {
            object version; object kind; if(!request.TryGetValue("version",out version)||Convert.ToInt32(version)!=ProtocolVersion||!request.TryGetValue("type",out kind))return Error("unsupported_request"); string type=kind as string; string username=Text(request,"username"),password=Text(request,"password"),identity=Text(request,"publicIdentity"),token=Text(request,"sessionToken");
            if(type=="register") { if(!ValidUsername(username)||String.IsNullOrEmpty(password)||password.Length>256||!ValidIdentity(identity)){Log("WARNING","Rejected malformed account registration.");return Error("invalid_registration");} if(accounts.UsernameExists(username)){Log("WARNING","Rejected duplicate account registration.");return Error("registration_failed");} if(accounts.DeviceIdentityExists(identity)){Log("WARNING","Rejected account registration because this public device identity is already registered.");return Error("device_already_registered");} var salt=new byte[16];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(salt); long id;try{id=accounts.CreateAccountWithDevice(username,salt,PasswordHash(password,salt),identity);Log("INFO","Account created: "+username+".");}catch(Exception error){Log("ERROR","Account registration storage failure: "+error.GetType().Name);return Error("registration_failed");}return Session(id); }
            if(type=="login") { if(!ValidUsername(username)||String.IsNullOrEmpty(password)||password.Length>256)return Error("login_failed");long id;bool ok=accounts.PasswordMatches(username,(salt,hash)=>ConstantTimeEquals(PasswordHash(password,salt),hash),out id);Log(ok?"INFO":"WARNING",ok?"Account authentication succeeded.":"Account authentication failed.");return ok?Session(id):Error("login_failed"); }
            long accountId=accounts.Authenticate(TokenHash(token)); if(accountId==0)return Error("session_invalid");
            if(type=="logout"){accounts.RevokeSession(TokenHash(token));Log("INFO","Account session signed out.");return Ok();}
            if(type=="presence") { bool directCandidates=Flag(request,"directCandidates",true);int endpointPort=0,publicPort=0;string endpointHost=Text(request,"endpointHost")??"",publicHost=Text(request,"publicEndpointHost")??"";if(!ValidIdentity(identity))return Error("invalid_presence");if(directCandidates){if(!Int32.TryParse(Text(request,"endpointPort"),out endpointPort)||!ValidEndpoint(endpointHost,endpointPort))return Error("invalid_presence");if(!Int32.TryParse(Text(request,"publicEndpointPort"),out publicPort))publicPort=0;}else{endpointHost="";endpointPort=0;publicHost="";publicPort=0;}string observedClassification="Not evaluated";string publicSource; if(!directCandidates){publicSource="Relay-only presence";}else if(String.IsNullOrEmpty(publicHost)){if(IsUsablePublicIpv4(observedHost,out observedClassification)){publicHost=observedHost;publicPort=endpointPort;publicSource="Server-observed Internet address";}else if(observedClassification.StartsWith("Loopback",StringComparison.Ordinal)&&IsLocalInterfaceAddress(endpointHost)){string configuredClassification;if(IsUsablePublicIpv4(config.SelfHostedPublicP2PHost,out configuredClassification)){publicHost=config.SelfHostedPublicP2PHost;publicPort=endpointPort;publicSource="Configured self-hosted P2P fallback";}else{publicHost="";publicPort=0;publicSource="No usable configured self-hosted P2P address";}}else{publicHost="";publicPort=0;publicSource="Observed address rejected";}}else{string suppliedClassification;if(!IsUsablePublicIpv4(publicHost,out suppliedClassification))return Error("invalid_public_endpoint");publicSource="Authenticated explicit public candidate";}if(!ValidEndpoint(publicHost,publicPort))return Error("invalid_public_endpoint");if(!accounts.AddDevice(accountId,identity))return Error("device_account_mismatch");accounts.TouchPresence(accountId,identity,endpointHost,endpointPort,publicHost,publicPort,publicSource,observedClassification);BroadcastPresence(accountId,identity,endpointHost,endpointPort,publicHost,publicPort);Log("DEBUG","Presence refreshed for account "+accountId+" ("+accounts.Username(accountId)+") direct candidates="+directCandidates+"; public candidate source: "+publicSource+".");return Ok(new Dictionary<string,object>{{"accountId",accountId},{"username",accounts.Username(accountId)??""},{"registeredPublicIdentity",identity},{"endpointHost",endpointHost},{"endpointPort",endpointPort},{"publicEndpointHost",publicHost},{"publicEndpointPort",publicPort},{"publicCandidateSource",publicSource},{"observedAddressClassification",observedClassification},{"directCandidatesEnabled",directCandidates}}); }
            if(type=="session_info")return Ok(new Dictionary<string,object>{{"accountId",accountId},{"username",accounts.Username(accountId)??""},{"relayOnlyPresence",true}});
            if(type=="search") { if(!ValidUsername(username)){Log("WARNING","Rejected malformed username search.");return Error("invalid_search");}var found=accounts.Search(username,accountId);Log("DEBUG",found==null?"Username search returned no result.":"Username search completed.");return found==null?Error("not_found"):Ok(found); }
            if(type=="suggest") { if(String.IsNullOrEmpty(username)||username.Length>32||username.Any(c=>!(Char.IsLetterOrDigit(c)||c=='-'||c=='_')))return Error("invalid_search");var suggestions=accounts.Suggestions(username,accountId,15);Log("DEBUG","Username suggestions completed: "+suggestions.Count+" result(s).");return Ok(new Dictionary<string,object>{{"suggestions",suggestions}}); }
            if(type=="friend_state")return Ok(accounts.FriendState(accountId));
            long other; if(!Int64.TryParse(Text(request,"accountId"),out other)||other<1)return Error("invalid_account");
            if(type=="friend_request"){var result=accounts.SendFriendRequest(accountId,other);Log(result=="pending"||result=="accepted_crossed"?"INFO":"WARNING","Friend request result: "+result+".");if(result=="pending"||result=="accepted_crossed")Broadcast(accountId,other,result=="accepted_crossed"?"friendship_changed":"friend_request");return result=="pending"||result=="accepted_crossed"?Ok(new Dictionary<string,object>{{"state",result}}):Error(result);}
            if(type=="friend_respond"){bool accept=String.Equals(Text(request,"action"),"accept",StringComparison.Ordinal);var result=accounts.RespondToRequest(accountId,other,accept);Log(result=="friends"||result=="rejected"?"INFO":"WARNING","Friend request response result: "+result+".");if(result=="friends"||result=="rejected")Broadcast(accountId,other,accept?"friendship_changed":"friend_request_updated");return result=="friends"||result=="rejected"?Ok(new Dictionary<string,object>{{"state",result}}):Error(result);}
            if(type=="friend_cancel"){var result=accounts.CancelRequest(accountId,other);if(result=="cancelled")Broadcast(accountId,other,"friend_request_updated");return result=="cancelled"?Ok(new Dictionary<string,object>{{"state",result}}):Error(result);}
            if(type=="friend_remove"){var result=accounts.RemoveFriend(accountId,other);if(result=="removed")Broadcast(accountId,other,"friendship_changed");return result=="removed"?Ok(new Dictionary<string,object>{{"state",result}}):Error(result);}
            if(type=="friend_block"||type=="friend_unblock"){var result=accounts.SetBlocked(accountId,other,type=="friend_block");if(result=="blocked"||result=="unblocked")Broadcast(accountId,other,"friendship_changed");return result=="blocked"||result=="unblocked"?Ok(new Dictionary<string,object>{{"state",result}}):Error(result);}
            return Error("unsupported_request");
        }
        Dictionary<string,object> Session(long accountId){string token=RandomToken();accounts.CreateSession(TokenHash(token),accountId,DateTimeOffset.UtcNow.AddHours(config.SessionHours).ToUnixTimeSeconds());return Ok(new Dictionary<string,object>{{"sessionToken",token},{"accountId",accountId},{"username",accounts.Username(accountId)??""},{"expiresInSeconds",config.SessionHours*3600},{"relayOnlyPresence",true}});}
        static string Text(Dictionary<string,object> r,string key){object value;return r.TryGetValue(key,out value)?value as string:null;} static bool Flag(Dictionary<string,object> r,string key,bool fallback){object value;if(!r.TryGetValue(key,out value)||value==null)return fallback;try{return Convert.ToBoolean(value);}catch{return fallback;}} static Dictionary<string,object> Ok(Dictionary<string,object> data=null){var result=new Dictionary<string,object>{{"ok",true},{"version",ProtocolVersion}};if(data!=null)foreach(var p in data)result[p.Key]=p.Value;return result;} static Dictionary<string,object> Error(string code){return new Dictionary<string,object>{{"ok",false},{"version",ProtocolVersion},{"error",code}};}
        readonly object logGate=new object();
        // Operational logs stay in the configured Logs directory. Rotate a single old file so a
        // long-running home server cannot grow an unbounded log beside its executable.
        void Log(string level,string text){string line=DateTime.UtcNow.ToString("o")+" ["+level+"] "+text;Console.WriteLine(line);try{lock(logGate){Directory.CreateDirectory(config.LogDirectory);string file=Path.Combine(config.LogDirectory,"peerchat-server.log");if(File.Exists(file)&&new FileInfo(file).Length>1024*1024){string previous=file+".1";if(File.Exists(previous))File.Delete(previous);File.Move(file,previous);}File.AppendAllText(file,line+Environment.NewLine);}}catch{/* Logging must never prevent the server from accepting clients. */}}
        public void Run(){startedUtc=DateTime.UtcNow;listener=new TcpListener(IPAddress.Any,config.Port);listener.Start(64);Log("INFO","PeerChat Server "+VersionInfo.Display+" listener started on 0.0.0.0:"+config.Port+" (TLS enabled).");ThreadPool.QueueUserWorkItem(_=>PresenceMonitor());if(!String.IsNullOrEmpty(managementPipe)){Log("INFO","Local management pipe ready: "+managementPipe);ThreadPool.QueueUserWorkItem(_=>ManagementLoop());}try{while(!stopping){try{var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(_=>Serve(client));}catch(SocketException){if(!stopping)throw;}}}finally{if(listener!=null)listener.Stop();List<EventClient> subscribers;lock(eventGate){subscribers=new List<EventClient>(eventClients);eventClients.Clear();onlineAccounts.Clear();}foreach(var subscriber in subscribers)subscriber.Dispose();accounts.Dispose();Log("INFO","Server shutdown complete.");}}
        static string DecodeAdminText(string value){try{return String.IsNullOrEmpty(value)?null:Encoding.UTF8.GetString(Convert.FromBase64String(value));}catch{return null;}}
        void ManagementLoop(){while(!stopping){try{using(var pipe=new NamedPipeServerStream(managementPipe,PipeDirection.InOut,4,PipeTransmissionMode.Byte,PipeOptions.None)){pipe.WaitForConnection();var encoding=new UTF8Encoding(false);var reader=new StreamReader(pipe,encoding,false,256,true);var writer=new StreamWriter(pipe,encoding,256,true);var command=reader.ReadLine()??"";Dictionary<string,object> response;if(command=="STATUS")response=Status();else if(command=="STOP"){response=new Dictionary<string,object>{{"ok",true}};RequestStop();}else if(command.StartsWith("ACCOUNT_LOOKUP ",StringComparison.Ordinal)){var account=accounts.AdminLookup(DecodeAdminText(command.Substring("ACCOUNT_LOOKUP ".Length)));response=account==null?Error("account_not_found"):Ok(account);}else if(command.StartsWith("DELETE_ACCOUNT ",StringComparison.Ordinal)){long id;response=Int64.TryParse(command.Substring("DELETE_ACCOUNT ".Length),out id)&&id>0?AdminDeleteAccount(id):Error("invalid_account_id");}else response=Error("unsupported_admin_command");writer.WriteLine(json.Serialize(response));writer.Flush();}}catch(Exception error){if(!stopping)Log("WARNING","Local admin pipe error: "+error.GetType().Name);}}}
        Dictionary<string,object> Status(){var data=accounts.Statistics();data["ok"]=true;data["running"]=!stopping;data["uptimeSeconds"]=(long)(DateTime.UtcNow-startedUtc).TotalSeconds;data["port"]=config.Port;data["address"]="0.0.0.0";data["tls"]=true;data["connectedClients"]=Interlocked.CompareExchange(ref connectedClients,0,0);return data;}
        void RequestStop(){if(stopping)return;stopping=true;Log("INFO","Graceful shutdown requested by local administration.");try{listener.Stop();}catch{}}
        // TLS is a byte stream, not a message transport. A four-byte big-endian length prefix
        // keeps partial reads from being mistaken for an entire JSON request.
        static byte[] ReadFrame(Stream stream,int maximum){var header=ReadExact(stream,4);if(header==null)return null;int length=(header[0]<<24)|(header[1]<<16)|(header[2]<<8)|header[3];return length<1||length>maximum?null:ReadExact(stream,length);}
        static byte[] ReadExact(Stream stream,int length){var bytes=new byte[length];int offset=0;while(offset<length){int read=stream.Read(bytes,offset,length-offset);if(read==0)return null;offset+=read;}return bytes;}
        static void WriteFrame(Stream stream,byte[] bytes){var header=new[]{(byte)(bytes.Length>>24),(byte)(bytes.Length>>16),(byte)(bytes.Length>>8),(byte)bytes.Length};stream.Write(header,0,header.Length);stream.Write(bytes,0,bytes.Length);}
        bool PairRelay(RelayEndpoint endpoint){
            lock(relayGate){
                if(activeRelayBindings.Contains(endpoint.Binding))return false;
                activeRelayBindings.Add(endpoint.Binding);
                RelayEndpoint peer=waitingRelays.FirstOrDefault(value=>value.AccountId==endpoint.TargetAccountId&&value.DeviceId==endpoint.TargetDeviceId&&value.TargetAccountId==endpoint.AccountId&&value.TargetDeviceId==endpoint.DeviceId);
                if(peer==null){waitingRelays.Add(endpoint);return true;}
                waitingRelays.Remove(peer);string session=RandomToken();endpoint.Peer=peer;peer.Peer=endpoint;endpoint.SessionId=peer.SessionId=session;
                endpoint.Incoming=String.CompareOrdinal(endpoint.DeviceId,peer.DeviceId)>0;peer.Incoming=!endpoint.Incoming;endpoint.Ready.Set();peer.Ready.Set();return true;
            }
        }
        void RemoveRelay(RelayEndpoint endpoint){lock(relayGate){waitingRelays.Remove(endpoint);relayEndpoints.Remove(endpoint);activeRelayBindings.Remove(endpoint.Binding);}try{if(endpoint.Peer!=null)endpoint.Peer.Client.Close();}catch{}endpoint.Ready.Dispose();}
        void RetireDeletedAccount(long accountId){List<EventClient> events;lock(eventGate){onlineAccounts.Remove(accountId);onlineCandidateSignatures.Remove(accountId);events=eventClients.Where(value=>value.AccountId==accountId).ToList();foreach(var value in events)eventClients.Remove(value);}foreach(var value in events)value.Dispose();List<RelayEndpoint> relays;lock(relayGate)relays=relayEndpoints.Where(value=>value.AccountId==accountId||value.TargetAccountId==accountId).ToList();foreach(var value in relays){try{value.Client.Close();}catch{}}}
        Dictionary<string,object> AdminDeleteAccount(long accountId){var deleted=accounts.AdminDeleteAccount(accountId);if(deleted==null)return Error("account_not_found");var related=deleted["relatedAccounts"] as List<long>;if(related!=null)foreach(var other in related)Broadcast(other,accountId,"friendship_changed",false);RetireDeletedAccount(accountId);Log("WARNING","Local administrator permanently deleted server account "+accountId+" ("+deleted["username"]+").");return Ok(new Dictionary<string,object>{{"state","account_deleted"},{"accountId",accountId},{"username",deleted["username"]}});}
        void ServeRelay(TcpClient client,SslStream tls,Dictionary<string,object> request){
            long accountId=accounts.Authenticate(TokenHash(Text(request,"sessionToken"))),targetAccountId;string device=Text(request,"publicIdentity"),targetDevice=Text(request,"targetPublicIdentity");
            if(accountId==0){WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Error("session_invalid"))));return;}
            if(!Int64.TryParse(Text(request,"targetAccountId"),out targetAccountId)||targetAccountId<1||accountId==targetAccountId||!ValidIdentity(device)||!ValidIdentity(targetDevice)||!accounts.OwnsDevice(accountId,device)||!accounts.OwnsDevice(targetAccountId,targetDevice)){WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Error("relay_identity_invalid"))));return;}
            if(!accounts.RelayAuthorized(accountId,targetAccountId)){WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Error("relay_not_authorized"))));return;}
            var endpoint=new RelayEndpoint(client,tls,accountId,device,targetAccountId,targetDevice);lock(relayGate)relayEndpoints.Add(endpoint);
            if(!PairRelay(endpoint)){lock(relayGate)relayEndpoints.Remove(endpoint);WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Error("relay_duplicate_attachment"))));return;}
            try{
                if(!endpoint.Ready.WaitOne(TimeSpan.FromSeconds(15))){WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Error("relay_pair_timeout"))));return;}
                var ready=Encoding.UTF8.GetBytes(json.Serialize(Ok(new Dictionary<string,object>{{"type","relay_ready"},{"sessionId",endpoint.SessionId},{"incoming",endpoint.Incoming}})));lock(endpoint.WriteGate)WriteFrame(tls,ready);
                byte[] session=Encoding.ASCII.GetBytes(endpoint.SessionId);
                while(!stopping){var frame=ReadFrame(tls,session.Length+MaxRelayPayloadBytes);if(frame==null||frame.Length<=session.Length)return;for(int i=0;i<session.Length;i++)if(frame[i]!=session[i])return;var peer=endpoint.Peer;if(peer==null||peer.SessionId!=endpoint.SessionId)return;lock(peer.WriteGate)WriteFrame(peer.Tls,frame);}
            }finally{RemoveRelay(endpoint);Log("DEBUG","Authenticated opaque relay channel closed for account "+accountId+".");}
        }
        void Serve(TcpClient client){Interlocked.Increment(ref connectedClients);Log("DEBUG","Discovery client connected.");using(client)using(var tls=new SslStream(client.GetStream(),false)){try{tls.AuthenticateAsServer(certificate,false,System.Security.Authentication.SslProtocols.Tls12|System.Security.Authentication.SslProtocols.Tls13,false);var bytes=ReadFrame(tls,MaxRequestBytes);if(bytes==null)return;var request=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(bytes));string requestType=Text(request,"type");
                if(requestType=="relay_attach"){ServeRelay(client,tls,request);return;}
                // Event subscriptions are authenticated with the same short-lived session token
                // as ordinary requests. The server sends notifications only; clients fetch the
                // authoritative friend snapshot after each notification. This keeps the channel
                // useful for presence and request updates without making it a second data store.
                if(requestType=="events"){
                    long eventAccount=accounts.Authenticate(TokenHash(Text(request,"sessionToken")));
                    if(eventAccount==0){WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Error("session_invalid"))));return;}
                    WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(Ok(new Dictionary<string,object>{{"type","events_ready"}}))));
                    var subscription=new EventClient(client,tls,eventAccount);lock(eventGate)eventClients.Add(subscription);Log("DEBUG","Authenticated discovery event channel opened.");
                    // Keep the authenticated notification socket open until the client or
                    // server actually closes it.  SelectRead can also be raised while bytes
                    // are buffered; treating every readable state as EOF caused needless
                    // event-channel churn and forced clients back to short-lived polling.
                    try{while(!stopping){if(client.Client.Poll(500000,SelectMode.SelectRead)&&client.Available==0)break;} }
                    finally{lock(eventGate)eventClients.Remove(subscription);subscription.Dispose();Log("DEBUG","Discovery event channel closed.");}
                    return;
                }
                string observedHost="";try{var remote=client.Client.RemoteEndPoint as IPEndPoint;if(remote!=null)observedHost=remote.Address.ToString();}catch{}var response=Encoding.UTF8.GetBytes(json.Serialize(Handle(request,observedHost,0)));WriteFrame(tls,response);}catch(Exception error){Log("WARNING","Client request failed: "+error.GetType().Name);}finally{Interlocked.Decrement(ref connectedClients);Log("DEBUG","Discovery client disconnected.");}}}
        public static int Main(string[] args){try{string configPath=ServerConfiguration.DefaultConfigPath;for(int i=0;i+1<args.Length;i++)if(args[i]=="--config")configPath=args[++i];var c=ServerConfiguration.Load(configPath);for(int i=0;i+1<args.Length;i++){if(args[i]=="--port")c.Port=Int32.Parse(args[++i],CultureInfo.InvariantCulture);else if(args[i]=="--database")c.DatabasePath=args[++i];else if(args[i]=="--certificate")c.CertificatePath=args[++i];else if(args[i]=="--certificate-password")c.CertificatePassword=args[++i];else if(args[i]=="--certificate-thumbprint")c.CertificateThumbprint=args[++i];else if(args[i]=="--management-pipe")c.ManagementPipe=args[++i];}c.Validate();new DiscoveryServer(c).Run();return 0;}catch(Exception error){Console.Error.WriteLine("PeerChat server startup failed: "+error.GetType().Name+": "+error.Message);return 1;}}
    }
}
